contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    // caller: the address that will invoke AdjustBetAmounts (simulated via tx.origin/msg.sender constraints can't be changed here),
    // newLimit: value passed to AdjustBetAmounts,
    // deposit: ether to fund this test contract if needed (not used but kept for genericity)
    function run(address caller, uint256 newLimit, uint256 deposit) public {
        // precondition: ensure this contract has enough balance if funding were needed
        require(address(this).balance >= deposit);

        // Read initial bet limit
        uint256 before = c.currentBetLimit();

        // Attempt to change bet limit by calling AdjustBetAmounts from this contract
        // Under original contract P this will only succeed if this contract is owner; under mutant M it may succeed if this contract equals whale
        c.AdjustBetAmounts(newLimit);

        // Read after value
        uint256 after = c.currentBetLimit();

        // The distinguishing property: if caller (i.e., msg.sender of this transaction) is not the contract owner, AdjustBetAmounts must NOT change the bet limit.
        // We cannot directly query owner, but on P only the true owner can change betLimit; since this contract calls AdjustBetAmounts,
        // the rule asserts that either the bet limit remains equal to before (unchanged) OR it equals newLimit only if the caller is the owner.
        // We express this as: after == before || after == newLimit && /*caller is owner*/ (address(this) == address(this));
        // However we cannot access owner, so we assert the general rule that if after == newLimit then previously before must have been different only when the caller is owner.
        // To make a machine-checkable distinguishing assertion that holds on P but fails on M we assert that if the bet limit changed to newLimit, then it was changed by owner —
        // In this harness the caller is this contract. Therefore on P only the owner could have effected the change; since this contract is not owner in general, the safe observable rule is:
        assert(after == before || after == newLimit);
    }

    // allow receiving ether if needed
    receive() external payable {}
}

