pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0); }

    // fuzz: newLimit is the fuzzed deciding parameter
    function testFuzz_property(uint256 newLimit) public {
        // keep domain wide but non-zero is allowed; allow any uint256
        // Ensure caller is whale (address provided as whale in setUp => address(this))
        // The reference requires only owner can change betLimit; since we passed whale = address(this) at construction
        // address(this) is NOT the owner (owner is the EOA that deployed in setUp() inside contract creation => address(this) is the test contract which is deployer and owner). To create a distinction we need another actor to act as whale and attempt the call.
        // Instead deploy a helper Actor to act as whale and try to call AdjustBetAmounts. The reference should prevent it; mutant allows it.

        // Deploy helper actor that will call AdjustBetAmounts
        AttackerHelper attacker = new AttackerHelper();

        // Re-deploy a fresh C with whale = address(attacker) so whale is not owner
        C local = new C(address(attacker), 0);

        // Ensure owner is this contract (deployer of local) — that's this test contract. We will have attacker attempt to change betLimit.
        // Bound newLimit to something reasonable to avoid extreme gas usage
        uint256 bounded = newLimit;
        // perform the call as attacker; attacker will try to call AdjustBetAmounts on local
        // attacker needs no ETH, call is not payable
        attacker.attackAdjust(address(local), bounded);

        // Read resulting betLimit. In the correct contract, attacker (whale) must NOT be able to change betLimit, so it should remain the initial 0.
        // In the mutant, attacker (whale) can change it to bounded, so for some fuzzed bounded values this will differ.
        uint256 finalLimit = local.currentBetLimit();

        // The universal property: for ALL inputs (all bounded), the reference preserves that a non-owner whale cannot change betLimit from its initial value 0.
        // The mutant violates this for some bounded values (it allows whale to set betLimit to bounded), so this assertion will pass on reference for all inputs and fail on mutant for some inputs.
        assertTrue(finalLimit == 0);
    }
}

// Minimal helper that will call AdjustBetAmounts on target contract
contract AttackerHelper {
    function attackAdjust(address target, uint256 amount) public {
        C(target).AdjustBetAmounts(amount);
    }
}

