    // Drive the contract: attempt to change difficulty and observe that it did not change
    // unless this test contract is the owner. We express that by recording the difficulty
    // before and after calling AdjustDifficulty and asserting they are equal.
    function run(uint256 newDifficulty) public {
        uint256 before = c.currentDifficulty();
        // call AdjustDifficulty; in P this will revert for non-owners, so ensure it doesn't revert here
        // but per constraints we must perform the state-changing call as its own top-level statement.
        // If this contract is not the owner, P will revert and the call will fail; to make a single
        // assert that distinguishes the mutant, we allow both behaviors but require that on-success
        // the difficulty still equals the prior value (owner-only in P ensures others cannot change it).
        // However AdjustDifficulty is protected by onlyOwner in P; in M it allows anyone and will set it.
        // We perform a low-level call to capture success without reverting the test.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("AdjustDifficulty(uint256)", newDifficulty));
        uint256 after = c.currentDifficulty();
        // If the call succeeded but the difficulty changed, that's only possible in M.
        // The assertion states: either the call failed (not owner in P) OR the difficulty remained unchanged.
        // This holds for P for any caller (call fails for non-owner; if caller is owner, owner may change but
        // the test contract would have to be owner which is not generally true). In mutant M a non-owner
        // call can succeed and change the difficulty, violating the assertion.
        assert((!ok) || (after == before));
    }

    // allow contract to receive ether if needed
    receive() external payable {}
}

